import{_ as a,c as s,a3 as i,o as t}from"./chunks/framework.DLXsHQLa.js";const u=JSON.parse('{"title":"GRUB2 字体过大、分辨率偏低排查与设置指南","description":"","frontmatter":{},"headers":[],"relativePath":"Linux系统/GRUB2分辨率与字体大小排查指南.md","filePath":"Linux系统/GRUB2分辨率与字体大小排查指南.md","lastUpdated":1794798679000}'),n={name:"Linux系统/GRUB2分辨率与字体大小排查指南.md"};function l(o,e,d,r,p,c){return t(),s("div",null,e[0]||(e[0]=[i('<h1 id="grub2-字体过大、分辨率偏低排查与设置指南" tabindex="-1">GRUB2 字体过大、分辨率偏低排查与设置指南 <a class="header-anchor" href="#grub2-字体过大、分辨率偏低排查与设置指南" aria-label="Permalink to &quot;GRUB2 字体过大、分辨率偏低排查与设置指南&quot;">​</a></h1><h2 id="一、原因说明" tabindex="-1">一、原因说明 <a class="header-anchor" href="#一、原因说明" aria-label="Permalink to &quot;一、原因说明&quot;">​</a></h2><p>GRUB2 界面字体显得很大、分辨率偏低，通常是因为 <strong>GRUB 阶段工作在低分辨率显示模式下</strong>（例如 <code>640x480</code>、<code>800x600</code> 或 <code>1024x768</code>），被高分辨率显示器全屏拉伸所致。</p><p>结合当前系统配置（UEFI 启动，存在 <code>/sys/firmware/efi</code>），主要原因如下：</p><ol><li><strong>未显式指定分辨率</strong>：<code>/etc/default/grub</code> 中 <code>#GRUB_GFXMODE=640x480</code> 目前处于注释状态，GRUB2 默认按 <code>auto</code> 直接沿用主板固件提供的默认显示模式。</li><li><strong>UEFI 固件默认 GOP 分辨率偏低</strong>：GRUB 阶段尚未加载 Linux 显卡驱动，完全依赖主板 UEFI 固件的 GOP 输出。部分主板（尤其是开启了 CSM 兼容模式，或外接显示器握手异常时）默认只输出低分辨率。</li><li><strong>默认字体在低分辨率下占比大</strong>：GRUB2 默认使用约 16px 的 <code>unicode.pf2</code> 点阵字体，在低分辨率下会显得非常大。</li></ol><hr><h2 id="二、排查与解决步骤" tabindex="-1">二、排查与解决步骤 <a class="header-anchor" href="#二、排查与解决步骤" aria-label="Permalink to &quot;二、排查与解决步骤&quot;">​</a></h2><h3 id="_1-查看-grub-实际支持的分辨率" tabindex="-1">1. 查看 GRUB 实际支持的分辨率 <a class="header-anchor" href="#_1-查看-grub-实际支持的分辨率" aria-label="Permalink to &quot;1. 查看 GRUB 实际支持的分辨率&quot;">​</a></h3><ol><li>重启电脑进入 GRUB 菜单。 <blockquote><p><strong>注意</strong>：当前 <code>/etc/default/grub</code> 配置了 <code>GRUB_TIMEOUT_STYLE=hidden</code> 和 <code>GRUB_TIMEOUT=0</code>，开机时可能需要按住 <code>Shift</code> 或连按 <code>Esc</code> 才能唤出 GRUB 菜单。</p></blockquote></li><li>在 GRUB 菜单界面按 <code>c</code> 进入命令行，输入：<div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>videoinfo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>记下输出列表中支持的分辨率（例如 <code>1920x1080x32</code>、<code>2560x1440x32</code> 等）。</li><li>按 <code>Esc</code> 返回菜单继续启动系统。</li></ol><h3 id="_2-修改-etc-default-grub" tabindex="-1">2. 修改 <code>/etc/default/grub</code> <a class="header-anchor" href="#_2-修改-etc-default-grub" aria-label="Permalink to &quot;2. 修改 `/etc/default/grub`&quot;">​</a></h3><p>编辑配置文件：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFCB6B;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> /etc/default/grub</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>取消 <code>GRUB_GFXMODE</code> 的注释并修改为 <code>videoinfo</code> 中确认支持的分辨率（建议末尾保留 <code>,auto</code> 作为兜底）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#BABED8;">GRUB_GFXMODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#89DDFF;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;">1920x1080,auto</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#BABED8;">GRUB_GFXPAYLOAD_LINUX</span><span style="--shiki-light:#D73A49;--shiki-dark:#89DDFF;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;">keep</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><em>(请将 <code>1920x1080</code> 替换为实际需要且 <code>videoinfo</code> 支持的分辨率)</em></p><h3 id="_3-更新-grub-配置" tabindex="-1">3. 更新 GRUB 配置 <a class="header-anchor" href="#_3-更新-grub-配置" aria-label="Permalink to &quot;3. 更新 GRUB 配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFCB6B;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> update-grub</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>完成后重启即可生效。</p><hr><h2 id="三、补充排查与进阶调整" tabindex="-1">三、补充排查与进阶调整 <a class="header-anchor" href="#三、补充排查与进阶调整" aria-label="Permalink to &quot;三、补充排查与进阶调整&quot;">​</a></h2><ul><li><strong>若 <code>videoinfo</code> 最高仅显示 <code>1024x768</code> 等低分辨率</strong>： 进入主板 BIOS/UEFI 设置，关闭 <strong>CSM（Compatibility Support Module / 兼容支持模块）</strong>，确保纯 UEFI 模式启动，通常即可恢复高分辨率 GOP 输出。</li><li><strong>单独调整 GRUB 字体大小</strong>： 如果调高分辨率后觉得字体太小或仍需调整，可用 <code>grub-mkfont</code> 从系统字体生成指定像素大小的 <code>.pf2</code> 字体，并在 <code>/etc/default/grub</code> 中通过 <code>GRUB_FONT</code> 指定：<div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFCB6B;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> grub-mkfont</span><span style="--shiki-light:#005CC5;--shiki-dark:#C3E88D;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#F78C6C;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#C3E88D;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> /boot/grub/fonts/custom.pf2</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> /usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>然后在 <code>/etc/default/grub</code> 中添加：<div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#BABED8;">GRUB_FONT</span><span style="--shiki-light:#D73A49;--shiki-dark:#89DDFF;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;">/boot/grub/fonts/custom.pf2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>修改后同样需要执行 <code>sudo update-grub</code>。</li></ul>',21)]))}const b=a(n,[["render",l]]);export{u as __pageData,b as default};
